import {
  Button,
  FieldError,
  Group,
  Input,
  Label,
  NumberField as AriaNumberField,
  Text,
} from "react-aria-components";
import type {
  NumberFieldProps as AriaNumberFieldProps,
  ValidationResult,
} from "react-aria-components";
import { Minus, Plus } from "./icons";
import type { ReactNode, Ref } from "react";
import { roleSize, type ControlSize } from "./controlSize";
import "./NumberField.css";

type NumberFieldSize = Exclude<ControlSize, "x-small">;
type NumberFieldLayout = "end" | "split";

export interface NumberFieldProps extends Omit<AriaNumberFieldProps, "className" | "children"> {
  /**
   * Size axis. No `x-small`: at 24px the two steppers cannot each hold their glyph beside a seam,
   * and each would be a press target narrower than the 24px WCAG 2.5.8 asks for.
   *
   * @default "medium"
   */
  size?: NumberFieldSize;
  /**
   * Where the steppers sit. `end` keeps both after the value, as one chip; `split` puts decrement
   * before the value and increment after it (`− n +`), with the field taking the brand's control corner.
   *
   * @default "end"
   */
  layout?: NumberFieldLayout;
  /** Field label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Helper text below the input. */
  description?: string;
  /** Message shown when validation fails. */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Input placeholder. */
  placeholder?: string;
  /** Additional class. sd-number-field is always retained. */
  className?: string;
  /** Passed to the underlying input DOM element. */
  ref?: Ref<HTMLInputElement>;
}

export function NumberField({
  size = "medium",
  layout = "end",
  label,
  contextualHelp,
  description,
  errorMessage,
  placeholder,
  className,
  ref,
  ...props
}: NumberFieldProps) {
  // No aria-label on either stepper: RAC's NumberField supplies a localized, field-specific name to
  // the increment/decrement buttons via ButtonContext (e.g. "Increase Seats"); an explicit
  // aria-label would override it (useContextProps mergeProps precedence). Built once here because
  // `layout` decides which side of the input it renders on.
  const decrement = (
    <Button
      slot="decrement"
      data-stepper="decrement"
      data-size={size}
      data-layout={layout}
      className="sd-number-field__stepper"
    >
      <Minus aria-hidden size="1em" />
    </Button>
  );
  return (
    <AriaNumberField
      {...props}
      data-size={size}
      className={className ? `sd-number-field ${className}` : "sd-number-field"}
    >
      {contextualHelp ? (
        <div className="sd-number-field__label-group">
          {label && <Label className={`sd-number-field__label sd-type-label-${roleSize(size)}`}>{label}</Label>}
          {contextualHelp}
        </div>
      ) : (
        label && <Label className={`sd-number-field__label sd-type-label-${roleSize(size)}`}>{label}</Label>
      )}
      <Group data-size={size} data-layout={layout} className="sd-number-field__group">
        {/* split: decrement is placed BEFORE the input in the DOM, not moved there with CSS `order`,
            because a screen reader's reading order follows the DOM. */}
        {layout === "split" && decrement}
        <Input
          ref={ref}
          data-size={size}
          data-layout={layout}
          placeholder={placeholder}
          className={`sd-number-field__input sd-type-body-${roleSize(size)}`}
        />
        {layout === "end" && decrement}
        <Button
          slot="increment"
          data-stepper="increment"
          data-size={size}
          data-layout={layout}
          className="sd-number-field__stepper"
        >
          {/* The rule between the two steppers. A real element, not a pseudo, for two reasons: the
              stepper needs three layers (divider, state overlay, touch-target) and has only two
              pseudos, and Figma already models this as its own `divider` node — so the element is
              what the layer tree expects (projection §5). Decorative only.
              `end` only: it splits ONE chip into two halves. In `split` each stepper is a chip of its
              own and the value already stands between them, so there is no seam to mark, and a rule
              beside each button would fence the value into a third box. */}
          {layout === "end" && <span aria-hidden="true" className="sd-number-field__divider" />}
          <Plus aria-hidden size="1em" />
        </Button>
      </Group>
      {description && (
        <Text slot="description" className={`sd-number-field__description sd-type-caption-${roleSize(size)}`}>
          {description}
        </Text>
      )}
      <FieldError className={`sd-number-field__error sd-type-caption-${roleSize(size)}`}>{errorMessage}</FieldError>
    </AriaNumberField>
  );
}

.sd-number-field {
  --sd-number-field-group-background-current: var(--sd-number-field-group-background);
  display: flex;
  flex-direction: column;
  gap: var(--sd-number-field-gap);
}
.sd-number-field[data-readonly] {
  --sd-number-field-group-background-current: var(--sd-number-field-group-background-readonly);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-number-field__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-number-field-label-group-gap);
}

.sd-number-field__label {
  padding-inline: var(--sd-number-field-text-padding-inline);
  color: var(--sd-number-field-label-foreground);
}

.sd-number-field__group {
  --sd-number-field-group-radius-current: var(--sd-number-field-group-radius-medium);
  display: grid;
  grid-template-columns: 1fr auto auto;
  width: 100%;
  overflow: hidden;
  background: var(--sd-number-field-group-background-current);
  color: var(--sd-number-field-group-foreground);
  border: var(--sd-number-field-group-border-width) solid var(--sd-number-field-group-border);
  border-radius: var(--sd-number-field-group-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-number-field__group[data-hovered] {
  border-color: var(--sd-number-field-group-border-hover);
}
.sd-number-field__group[data-focus-within] {
  border-color: var(--sd-number-field-group-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-number-field__group[data-invalid] {
  border-color: var(--sd-number-field-group-border-invalid);
}
/* invalid + focused: tint the focus ring red so it doesn't clash with the red border
   (matches TextField's invalid-focus register). */
.sd-number-field__group[data-invalid][data-focus-within] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-number-field-group-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-number-field__group[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-number-field__input {
  min-width: 0;
  /* A value wider than the field ends in an ellipsis while it rests, not at a hard clip mid-glyph;
     focused, the input scrolls to the caret as it always has. */
  text-overflow: ellipsis;
  width: 100%;
  background: transparent;
  color: var(--sd-number-field-input-foreground);
  border: 0;
  outline: 0;
  padding-inline-end: 0;
}
.sd-number-field__input::placeholder {
  color: var(--sd-number-field-input-placeholder);
}

.sd-number-field__group[data-size="small"] {
  --sd-number-field-group-radius-current: var(--sd-number-field-group-radius-small);
  min-height: var(--sd-number-field-group-height-small);
}
.sd-number-field__group[data-size="medium"] {
  --sd-number-field-group-radius-current: var(--sd-number-field-group-radius-medium);
  min-height: var(--sd-number-field-group-height-medium);
}
.sd-number-field__group[data-size="large"] {
  --sd-number-field-group-radius-current: var(--sd-number-field-group-radius-large);
  min-height: var(--sd-number-field-group-height-large);
}
.sd-number-field__group[data-size="x-large"] {
  --sd-number-field-group-radius-current: var(--sd-number-field-group-radius-x-large);
  min-height: var(--sd-number-field-group-height-x-large);
}
.sd-number-field__input[data-size="small"] {
  padding-inline-start: var(--sd-number-field-input-padding-inline-small);
}
.sd-number-field__input[data-size="medium"] {
  padding-inline-start: var(--sd-number-field-input-padding-inline-medium);
}
.sd-number-field__input[data-size="large"] {
  padding-inline-start: var(--sd-number-field-input-padding-inline-large);
}
.sd-number-field__input[data-size="x-large"] {
  padding-inline-start: var(--sd-number-field-input-padding-inline-x-large);
}

/* layout="split", `− n +`: the steppers flank the value. The corner is the group's own
   `radius.control`, the same as `end`: the shape follows the brand.
   Decrement comes first in the DOM (NumberField.tsx), so the grid needs no `order`. */
.sd-number-field__group[data-layout="split"] {
  grid-template-columns: auto 1fr auto;
}
/* Centred between two chips, which already keep their own inset from it, so the value takes no
   inline padding on either side: centred text looks the same either way, and padding would only cost
   the room a usage context's taller chips leave. Tabular figures
   keep the value from shifting sideways as its digits change under the steppers. The size rules
   below are more specific than the leading-padding ones above, so they must restate the zero. */
.sd-number-field__input[data-layout="split"],
.sd-number-field__input[data-layout="split"][data-size] {
  padding-inline: 0;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

.sd-number-field__stepper {
  /* Resting "chip": the steppers ARE buttons, so they read as one at rest — a filled surface
     inset 4px from the field edges (like SegmentedControl). The two steppers touch in the middle
     (only outer corners round) so they read as ONE continuous chip with the divider between them;
     hover/pressed darken each half via ::after. */
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* Square chip — width stated per size, NOT derived.
   The chip is 1:1, so the stepper's width is the row height MINUS ONE inset: the block inset
   applies twice (top+bottom) but the inline inset only once, because the two halves touch in
   the middle and only their OUTER edges are inset. Subtracting two would leave the chip 34x30 at
   medium instead of 30x30.
     `aspect-ratio: 1` would never fire: in a grid the `auto` COLUMN is sized first from the chip's
     intrinsic content (the glyph), and only then does `align-items: stretch` make the height
     definite. Both axes end up definite, and `aspect-ratio` applies only while one is auto, so the
     chip would render as a tall pill.
     The height is the row minus its block inset, so the width says exactly that. */
  /* The UA's own `<button>` padding (`1px 6px` in Chrome) — `reset.css` only normalizes a button's
     font and color, not its box. With `aspect-ratio` the 6px inline padding widens the chip's
     intrinsic size and that width transfers BACK into the height: at `small` it demanded a 24px chip
     in a row that only had 22, pushing the field from 32 to 34 (measured). Literal 0 rather than a
     token — an explicit "no box of its own", not a spacing decision. */
  color: var(--sd-number-field-stepper-foreground);
  border: 0;
  font: inherit;
  cursor: pointer;
  user-select: none;
  /* Same structure as Figma: the button is a square hit area the row's height, and the visible chip
     sits inside it. A chip that IS the button (margin + aspect-ratio) has its width fixed first by
     the glyph's intrinsic width and turns into a tall pill. The width is pinned to the row height
     and `::before` draws the chip, so the hit area is 40 and needs no WCAG 2.5.8 helper box. */
  /* BLOCK only. A uniform inset would also push the two halves apart in the MIDDLE (an 8px gap at
     the seam), where the design has them touch so they read as one continuous chip with a divider
     between (see the `[data-stepper]` rules below, which own the OUTER inset + the outer corners). */
  /* MARGIN on the block axis, not padding. Padding moves the glyph inward but leaves the BOX at the
     full row height, and the state layer is `inset: 0` on that box, so hover would paint flush to
     the field's top and bottom borders. The chip must be smaller than the row. */
  margin-block: var(--sd-number-field-stepper-overlay-inset);
  padding: 0;
  background: none;

  outline: none;
}
/* decrement = left half of the chip: round the left corners, inset from the input on the left,
   flush against increment on the right. */
.sd-number-field__stepper[data-stepper="decrement"] {
  margin-inline-start: var(--sd-number-field-stepper-overlay-inset);
  border-start-start-radius: var(--sd-number-field-stepper-overlay-radius);
  corner-start-start-shape: superellipse(var(--sd-radius-curve));
  border-end-start-radius: var(--sd-number-field-stepper-overlay-radius);
  corner-end-start-shape: superellipse(var(--sd-radius-curve));
}
/* increment = right half: round the right corners, inset from the field edge on the right,
   flush against decrement on the left (where the divider sits). */
.sd-number-field__stepper[data-stepper="increment"] {
  margin-inline-end: var(--sd-number-field-stepper-overlay-inset);
  border-start-end-radius: var(--sd-number-field-stepper-overlay-radius);
  corner-start-end-shape: superellipse(var(--sd-radius-curve));
  border-end-end-radius: var(--sd-number-field-stepper-overlay-radius);
  corner-end-end-shape: superellipse(var(--sd-radius-curve));
}
/* split: each stepper is a whole chip at one end of the group. The outer inset above already sits on
   the outer edge for both (decrement leads, increment ends), so only the corners change: all four
   take the rung below the group's, as any part painted inside a bordered group does. */
.sd-number-field__stepper[data-layout="split"] {
  border-radius: var(--sd-number-field-stepper-overlay-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}
/* Square, sized to the field height per size — the same footprint as an icon-only Button
   at each size on the control-height scale. The glyph rides
   the icon scale, matching an icon-only Button — not the body font-size. */
.sd-number-field__stepper[data-size="small"] {
  font-size: var(--sd-number-field-stepper-icon-size-small);
}
.sd-number-field__stepper[data-size="medium"] {
  font-size: var(--sd-number-field-stepper-icon-size-medium);
}
.sd-number-field__stepper[data-size="large"] {
  font-size: var(--sd-number-field-stepper-icon-size-large);
}
.sd-number-field__stepper[data-size="x-large"] {
  font-size: var(--sd-number-field-stepper-icon-size-x-large);
}
/* A single short, vertically-centered divider sits BETWEEN the two steppers — on the
   leading edge of the increment (+) button only (none between the value and the − button).
   A real element rather than a pseudo: the stepper needs THREE layers (this, the ::after state
   overlay, and the ::before touch-target below) and only has two pseudos — and Figma already
   models this as its own `divider` node, so the element is what the layer tree expects (§5). */
.sd-number-field__divider {
  position: absolute;
  inset-block: var(--sd-number-field-stepper-divider-inset-block);
  inset-inline-start: 0;
  width: var(--sd-number-field-stepper-border-width);
  background: var(--sd-number-field-stepper-border);
  pointer-events: none;
}
/* WCAG 2.2 (2.5.8): guarantee a 24px min pointer target. The chip is sized by the field row, so at
   size=small it is 22 — under the minimum. Transparent overlay, so the painted chip is unchanged;
   inert at medium/large where the chip is already 30/38. Same idiom as Checkbox/Radio/Switch. */
/* Square by construction: the chip's height is the group's content row (its min-height minus
   the two borders) because the grid stretches it, so the WIDTH must state exactly that.
   `aspect-ratio: 1` cannot: a grid sizes the `auto` column from the glyph's intrinsic width FIRST,
   and only then does stretch make the height definite; with both axes definite `aspect-ratio` has
   nothing to derive, and the chip renders as a tall pill. */
.sd-number-field__stepper[data-size="small"] {
  width: calc(
    var(--sd-number-field-group-height-small) - 2 * var(--sd-number-field-group-border-width) -
    2 * var(--sd-number-field-stepper-overlay-inset)
  );
}
.sd-number-field__stepper[data-size="medium"] {
  width: calc(
    var(--sd-number-field-group-height-medium) - 2 * var(--sd-number-field-group-border-width) -
    2 * var(--sd-number-field-stepper-overlay-inset)
  );
}
.sd-number-field__stepper[data-size="large"] {
  width: calc(
    var(--sd-number-field-group-height-large) - 2 * var(--sd-number-field-group-border-width) -
    2 * var(--sd-number-field-stepper-overlay-inset)
  );
}
.sd-number-field__stepper[data-size="x-large"] {
  width: calc(
    var(--sd-number-field-group-height-x-large) - 2 * var(--sd-number-field-group-border-width) -
    2 * var(--sd-number-field-stepper-overlay-inset)
  );
}
/* WCAG 2.5.8 target expander. Centred on the BLOCK axis, but anchored to the stepper's OUTER
   inline edge — never centred inline. The two halves touch, so at `small` the chips are 22 wide
   and two 24-wide targets centred on them would have their centres only 22 apart: they overlap by
   2px at the seam, and whichever paints later wins the hit test, leaving the other short of 24.
   (2.5.8's spacing alternative fails there too — it wants 24 between centres.) Anchoring each
   target away from the seam makes them exactly adjacent instead of overlapping: `[seam−24, seam]`
   and `[seam, seam+24]`. Inert at medium/large, where the chip already exceeds 24. */
.sd-number-field__stepper::before {
  content: "";
  position: absolute;
  top: 50%;
  translate: 0 -50%;
  min-width: var(--sd-number-field-stepper-touch-target-size);
  min-height: var(--sd-number-field-stepper-touch-target-size);
}
/* decrement is the leading half: its seam is on the inline END, so it grows toward the start.
   Logical, not `left`/`right`: the grid mirrors under RTL, and a physical anchor would then grow
   each target INTO the seam, which is the overlap this rule exists to prevent. */
.sd-number-field__stepper[data-stepper="decrement"]::before {
  inset-inline-end: 0;
}
/* increment is the trailing half: seam on the inline START, so it grows toward the end. */
.sd-number-field__stepper[data-stepper="increment"]::before {
  inset-inline-start: 0;
}
/* split has no seam: the chips stand apart, so each target is centred on its chip, a square like
   the other expanders here. In a brand whose `radius.control` rounds the end into a semicircle at
   `small` (avocado), the group's clip cuts the square's outer corners; what it never cuts is the 24
   circle inscribed in it, whose centre is the chip's and which clears the clip arc in every brand. So WCAG 2.5.8 holds by the spacing exception, the two steppers
   standing a value apart. Anchored as above, the target would reach into the clipped end. */
.sd-number-field__stepper[data-layout="split"]::before {
  left: 50%;
  right: auto;
  translate: -50% -50%;
}
/* hover/pressed via the global state-layer overlay (ADR-0009). Slightly inset + rounded so the
   tint reads as a floating ghost-button affordance rather than a full-bleed square fill. */
.sd-number-field__stepper::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-number-field__stepper[data-hovered]::after {
  background: var(--sd-state-hover);
}
.sd-number-field__stepper[data-pressed]::after {
  background: var(--sd-state-pressed);
}
.sd-number-field__stepper[data-focus-visible] {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-number-field__stepper[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-number-field__description {
  padding-inline: var(--sd-number-field-text-padding-inline);
  color: var(--sd-number-field-description-foreground);
}
.sd-number-field__error {
  padding-inline: var(--sd-number-field-text-padding-inline);
  color: var(--sd-number-field-error-foreground);
}
